var NB = null;
function nbuf(c) { if (NB && NB.sampleRate === c.sampleRate) { return NB; } var n = c.sampleRate * 2, b = c.createBuffer(1, n, c.sampleRate), d = b.getChannelData(0); for (var i = 0; i < n; i++) { d[i] = Math.random() * 2 - 1; } NB = b; return b; }
