  var seq = [[67, 71, 74, 79], [67, 71, 74, 76, 79], [74, 71, 74, 79]][v], i, st;
  for (i = 0; i < seq.length; i++) { st = t + i * 0.11; fiddle(c, out, st, mtof(seq[i]) * P, i === seq.length - 1 ? 0.7 : 0.12, 0.5); }
