  var d = [0.6, 0.75, 0.45][v], pts = [[[0, 520], [0.18, 760], [0.6, 480]], [[0, 600], [0.3, 820], [0.75, 520]], [[0, 700], [0.12, 880], [0.45, 640]]][v];
