  bp.gain.value = 6; vg.gain.setValueAtTime(0, t); vg.gain.linearRampToValueAtTime(f * 0.012, t + Math.min(0.25, d));
  vib.connect(vg); vg.connect(o.frequency); o.connect(bp); bp.connect(lp); lp.connect(g); g.connect(out);
  g.gain.setValueAtTime(0.0001, t); g.gain.linearRampToValueAtTime(pk, t + 0.04); g.gain.setValueAtTime(pk * 0.85, t + Math.max(0.05, d - 0.05)); g.gain.exponentialRampToValueAtTime(0.0001, t + d + 0.08);
